// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *OrderAddress) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := tables.CompanyTable(company, OrderAddressTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (vendor_no, code)`,
		fmt.Sprintf("%s$Order_Address$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	var keys []sift.Key
	for _, spec := range orderAddressSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, OrderAddressTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, OrderAddressTableName, keys)
}

